python3 -c "
import sqlite3
conn = sqlite3.connect('Calendars-full.icbu/Calendar.sqlitedb')
cur = conn.cursor()
for table in ['Calendar', 'Location', 'CalendarItem']:
    try:
        cur.execute(f'SELECT * FROM {table} LIMIT 5')
        rows = cur.fetchall()
        print(f'--- {table} ({len(rows)} sample rows) ---')
        for r in rows: print(r)
    except Exception as e:
        print(table, 'error:', e)
"
